  startOver: { en: "Change my answers", si: "මගේ පිළිතුරු වෙනස් කරන්න", ta: "எனது பதில்களை மாற்று" },

  // ---- Planner: results ----
  "res.consumption": { en: "What your household eats", si: "ඔබේ නිවසේ පරිභෝජනය", ta: "உங்கள் வீட்டின் நுகர்வு" },
  "res.growPlan": { en: "Your grow plan", si: "ඔබේ වගා සැලසුම", ta: "உங்கள் வளர்ப்புத் திட்டம்" },
  "res.shopping": { en: "Shopping list", si: "මිලදී ගැනීමේ ලැයිස්තුව", ta: "வாங்க வேண்டிய பட்டியல்" },
