  "col.monthlyCost": { en: "Market cost per month", si: "මසකට වෙළඳපොළ වියදම", ta: "மாதச் சந்தைச் செலவு" },
  "col.plants": { en: "Plants (planted / needed)", si: "පැළ (සිටවූ / අවශ්‍ය)", ta: "செடிகள் (நடப்பட்டவை / தேவை)" },
  "col.space": { en: "Space (sq ft)", si: "ඉඩ (වර්ග අඩි)", ta: "இடம் (ச.அடி)" },
