  "account.title": { en: "Your account", si: "ඔබේ ගිණුම", ta: "உங்கள் கணக்கு" },
  "account.signInPrompt": { en: "Sign in with Google to keep your cart on every device, see your orders and save your plans.", si: "සෑම උපාංගයකම ඔබේ කරත්තය තබා ගැනීමට, ඇණවුම් බැලීමට සහ සැලසුම් සුරැකීමට Google සමඟ පුරනය වන්න.", ta: "எல்லா சாதனங்களிலும் கூடையை வைத்திருக்க, ஆர்டர்களைப் பார்க்க, திட்டங்களைச் சேமிக்க Google மூலம் உள்நுழையவும்." },
  "account.signInPrivacy": { en: "We store your name, email, cart, orders and saved plans in your account. Only you can see them; shop staff can see orders.", si: "අපි ඔබේ නම, ඊමේල්, කරත්තය, ඇණවුම් සහ සුරැකි සැලසුම් ඔබේ ගිණුමේ ගබඩා කරමු. ඒවා දැකිය හැක්කේ ඔබට පමණි; සාප්පු කාර්ය මණ්ඩලයට ඇණවුම් දැකිය හැක.", ta: "உங்கள் பெயர், மின்னஞ்சல், கூடை, ஆர்டர்கள், சேமித்த திட்டங்களை உங்கள் கணக்கில் சேமிக்கிறோம். அவற்றை நீங்கள் மட்டுமே பார்க்க முடியும்; ஆர்டர்களைக் கடை ஊழியர்கள் பார்க்கலாம்." },
  "account.notConfigured": { en: "Accounts are not set up yet. The shop, planner and cart still work without signing in.", si: "ගිණුම් තවම සකසා නැත. පුරනය නොවී සාප්පුව, සැලසුම්කරු සහ කරත්තය භාවිතා කළ හැක.", ta: "கணக்குகள் இன்னும் அமைக்கப்படவில்லை. உள்நுழையாமலே கடை, திட்டம், கூடை செயல்படும்." },
  "account.unavailable": { en: "Your account could not be loaded right now. Please try again later.", si: "ඔබේ ගිණුම දැන් පූරණය කළ නොහැක. පසුව නැවත උත්සාහ කරන්න.", ta: "உங்கள் கணக்கை இப்போது ஏற்ற முடியவில்லை. பின்னர் முயற்சிக்கவும்." },
