  "account.noOrders": { en: "No orders yet.", si: "තවම ඇණවුම් නැත.", ta: "இன்னும் ஆர்டர்கள் இல்லை." },
  "account.plans": { en: "My saved plans", si: "මගේ සුරැකි සැලසුම්", ta: "எனது சேமித்த திட்டங்கள்" },
  "account.noPlans": { en: "No saved plans yet.", si: "තවම සුරැකි සැලසුම් නැත.", ta: "இன்னும் சேமித்த திட்டங்கள் இல்லை." },
  "account.planLine": { en: "{people} people · {space} sq ft · {total}", si: "පුද්ගලයින් {people} · වර්ග අඩි {space} · {total}", ta: "{people} பேர் · {space} ச.அடி · {total}" },
  "account.signInFailed": { en: "Sign-in did not complete. Please try again.", si: "පුරනය සම්පූර්ණ නොවීය. කරුණාකර නැවත උත්සාහ කරන්න.", ta: "உள்நுழைவு முடியவில்லை. மீண்டும் முயற்சிக்கவும்." },
  "account.deleteFinish": { en: "Finish deleting account", si: "ගිණුම මැකීම අවසන් කරන්න", ta: "கணக்கு நீக்கத்தை முடிக்கவும்" },
  "account.delete": { en: "Delete account", si: "ගිණුම මකන්න", ta: "கணக்கை நீக்கு" },
  "account.deleteConfirm": { en: "Delete your account permanently? Your saved cart, orders and plans will be removed. This cannot be undone.", si: "ඔබේ ගිණුම ස්ථිරවම මකන්නද? ඔබේ කරත්තය, ඇණවුම් සහ සැලසුම් ඉවත් වේ. මෙය අහෝසි කළ නොහැක.", ta: "உங்கள் கணக்கை நிரந்தரமாக நீக்கவா? உங்கள் கூடை, ஆர்டர்கள், திட்டங்கள் நீக்கப்படும். இதைத் திரும்பப் பெற முடியாது." },
